CREATE TABLE IF NOT EXISTS classes(id text PRIMARY KEY,title text NOT NULL,subject text NOT NULL,description text NOT NULL DEFAULT '',code text NOT NULL UNIQUE,teacher_id text NOT NULL REFERENCES "user"(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS enrollments(class_id text REFERENCES classes(id) ON DELETE CASCADE,user_id text REFERENCES "user"(id) ON DELETE CASCADE,PRIMARY KEY(class_id,user_id));
CREATE TABLE IF NOT EXISTS materials(id text PRIMARY KEY,class_id text NOT NULL REFERENCES classes(id),title text NOT NULL,body text NOT NULL,url text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS progress(material_id text REFERENCES materials(id),user_id text REFERENCES "user"(id),completed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(material_id,user_id));
CREATE TABLE IF NOT EXISTS posts(id text PRIMARY KEY,class_id text NOT NULL REFERENCES classes(id),author_id text NOT NULL REFERENCES "user"(id),parent_id text REFERENCES posts(id),pinned boolean NOT NULL DEFAULT false,locked boolean NOT NULL DEFAULT false,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS quizzes(id text PRIMARY KEY,class_id text NOT NULL REFERENCES classes(id),title text NOT NULL,kind text NOT NULL DEFAULT 'practice',questions jsonb NOT NULL,duration integer NOT NULL CHECK(duration BETWEEN 1 AND 180),max_attempts integer NOT NULL DEFAULT 1 CHECK(max_attempts BETWEEN 1 AND 10),opens_at timestamptz,closes_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS attempts(id text PRIMARY KEY,quiz_id text NOT NULL REFERENCES quizzes(id),user_id text NOT NULL REFERENCES "user"(id),snapshot jsonb NOT NULL,answers jsonb NOT NULL DEFAULT '{}',started_at timestamptz NOT NULL DEFAULT now(),submitted_at timestamptz,score integer,details jsonb);
CREATE TABLE IF NOT EXISTS assignments(id text PRIMARY KEY,class_id text NOT NULL REFERENCES classes(id),title text NOT NULL,instructions text NOT NULL,rubric text NOT NULL DEFAULT '',due_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS submissions(id text PRIMARY KEY,assignment_id text NOT NULL REFERENCES assignments(id),user_id text NOT NULL REFERENCES "user"(id),body text NOT NULL,file_url text NOT NULL DEFAULT '',score integer CHECK(score BETWEEN 0 AND 100),feedback text NOT NULL DEFAULT '',submitted_at timestamptz NOT NULL DEFAULT now(),UNIQUE(assignment_id,user_id));
CREATE TABLE IF NOT EXISTS announcements(id text PRIMARY KEY,class_id text NOT NULL REFERENCES classes(id),body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id text PRIMARY KEY,actor_id text NOT NULL REFERENCES "user"(id),action text NOT NULL,target_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS attempts_user_quiz ON attempts(user_id,quiz_id);
CREATE INDEX IF NOT EXISTS posts_class ON posts(class_id,created_at);
CREATE INDEX IF NOT EXISTS enrollments_user ON enrollments(user_id);
